  // A little continuous fill keeps the lowest bounce from dropping out.
  let brightness=dot(light,vec3f(.22,.70,.08));
  let stepSize=select(.14,.10,ground);
  let band=valleyRampBand(brightness/stepSize,pixel,.42,.012)*stepSize;
